public class LinkedList<T> {
    private class Node {
        T data;
        Node next;
        Node(T data) { this.data = data; }
    }

    private Node head;
    private int size;

    public void addFirst(T data) {
        Node node = new Node(data);
        node.next = head;
        head = node;
        size++;
    }

    public void addLast(T data) {
        Node node = new Node(data);
        if (head == null) { head = node; size++; return; }
        Node curr = head;
        while (curr.next != null) curr = curr.next;
        curr.next = node;
        size++;
    }

    public T removeFirst() {
        if (head == null) throw new NoSuchElementException();
        T data = head.data;
        head = head.next;
        size--;
        return data;
    }

    public int size() { return size; }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("[");
        Node curr = head;
        while (curr != null) { sb.append(curr.data); if (curr.next != null) sb.append(", "); curr = curr.next; }
        return sb.append("]").toString();
    }
}

public class BinarySearch {
    public static <T extends Comparable<T>> int search(T[] arr, T target) {
        int lo = 0, hi = arr.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int cmp = arr[mid].compareTo(target);
            if (cmp == 0) return mid;
            else if (cmp < 0) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        Integer[] nums = {1, 3, 5, 7, 9, 11, 13, 15};
        System.out.println(search(nums, 7));   // 3
        System.out.println(search(nums, 6));   // -1
        System.out.println(search(nums, 15));  // 7

        String[] words = {"apple", "banana", "cherry", "date"};
        System.out.println(search(words, "cherry")); // 2
    }
}

