public class MergeSort {
    public static void sort(int[] arr, int left, int right) {
        if (left >= right) return;
        int mid = left + (right - left) / 2;
        sort(arr, left, mid);
        sort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }

    private static void merge(int[] arr, int l, int m, int r) {
        int[] temp = Arrays.copyOfRange(arr, l, r + 1);
        int i = 0, j = m - l + 1, k = l;
        while (i <= m - l && j <= r - l)
            arr[k++] = temp[i] <= temp[j] ? temp[i++] : temp[j++];
        while (i <= m - l) arr[k++] = temp[i++];
        while (j <= r - l) arr[k++] = temp[j++];
    }

    public static void main(String[] args) {
        int[] arr = {38, 27, 43, 3, 9, 82, 10};
        sort(arr, 0, arr.length - 1);
        System.out.println(Arrays.toString(arr));
    }
}

public class HashMap<K, V> {
    private static final int CAPACITY = 16;
    private LinkedList<Entry<K, V>>[] buckets;

    @SuppressWarnings("unchecked")
    public HashMap() {
        buckets = new LinkedList[CAPACITY];
        for (int i = 0; i < CAPACITY; i++) buckets[i] = new LinkedList<>();
    }

    record Entry<K, V>(K key, V value) {}

    private int hash(K key) { return Math.abs(key.hashCode() % CAPACITY); }

    public void put(K key, V value) {
        int idx = hash(key);
        buckets[idx].removeIf(e -> e.key().equals(key));
        buckets[idx].add(new Entry<>(key, value));
    }

    public Optional<V> get(K key) {
        return buckets[hash(key)].stream()
            .filter(e -> e.key().equals(key))
            .map(Entry::value)
            .findFirst();
    }

    public boolean containsKey(K key) { return get(key).isPresent(); }
}

