public class Retry<T> {
    public static <T> T withRetry(Callable<T> action, int maxAttempts, Duration delay) throws Exception {
        for (int i = 0; i < maxAttempts; i++) {
            try {
                return action.call();
            } catch (Exception e) {
                if (i == maxAttempts - 1) throw e;
                Thread.sleep(delay.toMillis() * (long) Math.pow(2, i));
            }
        }
        throw new IllegalStateException("Should not reach here");
    }
}

