    @Override
    public Iterator<Integer> iterator() {
        return new Iterator<>() {
            int current = start;
            public boolean hasNext() { return current < end; }
            public Integer next() { return current++; }
        };
    }

    public int size() { return end - start; }
    public boolean contains(int n) { return n >= start && n < end; }
}

public class BinarySearchTree<T extends Comparable<T>> {
    private T value;
    private BinarySearchTree<T> left, right;

    public BinarySearchTree(T value) { this.value = value; }

    public BinarySearchTree<T> insert(T val) {
        if (val.compareTo(value) < 0) {
            if (left == null) left = new BinarySearchTree<>(val);
            else left.insert(val);
        } else {
            if (right == null) right = new BinarySearchTree<>(val);
            else right.insert(val);
        }
        return this;
    }

    public boolean contains(T val) {
        int cmp = val.compareTo(value);
        if (cmp == 0) return true;
        return cmp < 0 ? (left != null && left.contains(val))
                       : (right != null && right.contains(val));
    }

    public List<T> inOrder() {
        List<T> result = new ArrayList<>();
        if (left != null) result.addAll(left.inOrder());
        result.add(value);
        if (right != null) result.addAll(right.inOrder());
        return result;
    }
}

public class ThreadPool {
    private final int nThreads;
    private final BlockingQueue<Runnable> queue;
    private final List<Thread> workers = new ArrayList<>();
    private volatile boolean running = true;

    public ThreadPool(int nThreads) {
        this.nThreads = nThreads;
        this.queue = new LinkedBlockingQueue<>();
        for (int i = 0; i < nThreads; i++) {
            Thread t = new Thread(() -> {
                while (running || !queue.isEmpty()) {
                    try {
                        Runnable task = queue.poll(100, TimeUnit.MILLISECONDS);
                        if (task != null) task.run();
                    } catch (InterruptedException e) { Thread.currentThread().interrupt(); break; }
                }
            });
            workers.add(t);
            t.start();
        }
    }

    public void submit(Runnable task) { queue.offer(task); }

    public void shutdown() {
        running = false;
        workers.forEach(Thread::interrupt);
    }
}

