public class Graph {
    private final Map<Integer, List<Integer>> adjacency = new HashMap<>();

    public void addEdge(int u, int v) {
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    public List<Integer> bfs(int start) {
        List<Integer> visited = new ArrayList<>();
        Set<Integer> seen = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(start);
        seen.add(start);
        while (!queue.isEmpty()) {
            int node = queue.poll();
            visited.add(node);
            for (int neighbor : adjacency.getOrDefault(node, List.of())) {
                if (seen.add(neighbor)) queue.offer(neighbor);
            }
        }
        return visited;
    }

    public List<Integer> dfs(int start) {
        List<Integer> visited = new ArrayList<>();
        dfsHelper(start, new HashSet<>(), visited);
        return visited;
    }

    private void dfsHelper(int node, Set<Integer> seen, List<Integer> visited) {
        if (!seen.add(node)) return;
        visited.add(node);
        adjacency.getOrDefault(node, List.of()).forEach(n -> dfsHelper(n, seen, visited));
    }
}

public class Cache<K, V> {
    private final Map<K, CacheEntry<V>> store = new ConcurrentHashMap<>();
    private final Duration ttl;

    public Cache(Duration ttl) { this.ttl = ttl; }

    private record CacheEntry<V>(V value, Instant expiry) {}

    public void put(K key, V value) {
        store.put(key, new CacheEntry<>(value, Instant.now().plus(ttl)));
    }

    public Optional<V> get(K key) {
        CacheEntry<V> entry = store.get(key);
        if (entry == null) return Optional.empty();
        if (Instant.now().isAfter(entry.expiry())) {
            store.remove(key);
            return Optional.empty();
        }
        return Optional.of(entry.value());
    }

    public V getOrCompute(K key, Supplier<V> supplier) {
        return get(key).orElseGet(() -> {
            V value = supplier.get();
            put(key, value);
            return value;
        });
    }

    public void evictExpired() {
        store.entrySet().removeIf(e -> Instant.now().isAfter(e.getValue().expiry()));
    }
}

public class Validator<T> {
    private final List<Predicate<T>> rules = new ArrayList<>();
    private final List<String> messages = new ArrayList<>();

    public Validator<T> addRule(Predicate<T> rule, String message) {
        rules.add(rule);
        messages.add(message);
        return this;
    }

    public List<String> validate(T value) {
        List<String> errors = new ArrayList<>();
        for (int i = 0; i < rules.size(); i++) {
            if (!rules.get(i).test(value)) errors.add(messages.get(i));
        }
        return errors;
    }

    public static void main(String[] args) {
        Validator<String> emailValidator = new Validator<String>()
            .addRule(s -> s != null && !s.isEmpty(), "Email cannot be empty")
            .addRule(s -> s.contains("@"), "Email must contain @")
            .addRule(s -> s.length() >= 5, "Email too short");

        System.out.println(emailValidator.validate("bad"));
        System.out.println(emailValidator.validate("user@example.com"));
    }
}

