public class ForkJoinExample extends RecursiveTask<Long> {
    private static final long THRESHOLD = 10_000;
    private final long[] arr;
    private final int start, end;

    public ForkJoinExample(long[] arr, int start, int end) {
        this.arr = arr; this.start = start; this.end = end;
    }

    @Override
    protected Long compute() {
        if (end - start <= THRESHOLD) {
            long sum = 0;
            for (int i = start; i < end; i++) sum += arr[i];
            return sum;
        }
        int mid = start + (end - start) / 2;
        ForkJoinExample left = new ForkJoinExample(arr, start, mid);
        ForkJoinExample right = new ForkJoinExample(arr, mid, end);
        left.fork();
        return right.compute() + left.join();
    }

    public static void main(String[] args) {
        long[] data = LongStream.rangeClosed(1, 1_000_000).toArray();
        ForkJoinPool pool = ForkJoinPool.commonPool();
        long result = pool.invoke(new ForkJoinExample(data, 0, data.length));
        System.out.println("Sum: " + result);
    }
}

public class Dijkstra {
    public static Map<Integer, Integer> shortestPaths(Map<Integer, List<int[]>> graph, int src) {
        Map<Integer, Integer> dist = new HashMap<>();
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, src});
        dist.put(src, 0);

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0], u = curr[1];
            if (d > dist.getOrDefault(u, Integer.MAX_VALUE)) continue;
            for (int[] edge : graph.getOrDefault(u, List.of())) {
                int v = edge[0], w = edge[1];
                int nd = d + w;
                if (nd < dist.getOrDefault(v, Integer.MAX_VALUE)) {
                    dist.put(v, nd);
                    pq.offer(new int[]{nd, v});
                }
            }
        }
        return dist;
    }
}

public sealed interface Free<F, A> permits Free.Pure, Free.Suspend {
    record Pure<F, A>(A value) implements Free<F, A> {}
    record Suspend<F, A>(F fa, Function<Object, Free<F, A>> next) implements Free<F, A> {}

    default <B> Free<F, B> map(Function<A, B> fn) {
        return switch (this) {
            case Pure<F, A> p -> new Pure<>(fn.apply(p.value()));
            case Suspend<F, A> s -> new Suspend<>(s.fa(), x -> s.next().apply(x).map(fn));
        };
    }
}

public class CAS<T> {
    private final AtomicReference<T> ref;

    public CAS(T initial) { ref = new AtomicReference<>(initial); }

    public T updateAndGet(UnaryOperator<T> fn) {
        T prev, next;
        do {
            prev = ref.get();
            next = fn.apply(prev);
        } while (!ref.compareAndSet(prev, next));
        return next;
    }

    public T get() { return ref.get(); }

    public boolean compareAndSwap(T expected, T update) {
        return ref.compareAndSet(expected, update);
    }
}

public class Trampoline<T> {
    private final Either<T, Supplier<Trampoline<T>>> value;

    private Trampoline(Either<T, Supplier<Trampoline<T>>> value) { this.value = value; }

    public static <T> Trampoline<T> done(T v) { return new Trampoline<>(Either.left(v)); }
    public static <T> Trampoline<T> more(Supplier<Trampoline<T>> s) { return new Trampoline<>(Either.right(s)); }

    public T run() {
        Trampoline<T> t = this;
        while (t.value.isRight()) t = t.value.getRight().get();
        return t.value.getLeft();
    }

    public <R> Trampoline<R> map(Function<T, R> fn) {
        return flatMap(v -> done(fn.apply(v)));
    }

    public <R> Trampoline<R> flatMap(Function<T, Trampoline<R>> fn) {
        return more(() -> value.isLeft() ? fn.apply(value.getLeft()) : more(() -> value.getRight().get().flatMap(fn)));
    }
}

