public class EffectSystem {
    private static final ThreadLocal<Set<Class<?>>> ALLOWED = new ThreadLocal<>();

    public static <T> T withEffects(Set<Class<?>> effects, Supplier<T> action) {
        ALLOWED.set(effects);
        try { return action.get(); }
        finally { ALLOWED.remove(); }
    }

    public static void checkEffect(Class<?> effect) {
        Set<Class<?>> allowed = ALLOWED.get();
        if (allowed != null && !allowed.contains(effect))
            throw new IllegalStateException("Effect not allowed: " + effect.getName());
    }
}

public class Lock<T> {
    private T value;
    private final ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();

    public Lock(T initial) { this.value = initial; }

    public <R> R read(Function<T, R> fn) {
        rwLock.readLock().lock();
        try { return fn.apply(value); }
        finally { rwLock.readLock().unlock(); }
    }

    public void write(UnaryOperator<T> fn) {
        rwLock.writeLock().lock();
        try { value = fn.apply(value); }
        finally { rwLock.writeLock().unlock(); }
    }

    public <R> R modify(Function<T, Map.Entry<T, R>> fn) {
        rwLock.writeLock().lock();
        try { var entry = fn.apply(value); value = entry.getKey(); return entry.getValue(); }
        finally { rwLock.writeLock().unlock(); }
    }
}

public class TypeToken<T> {
    private final Type type;

    protected TypeToken() {
        Type superclass = getClass().getGenericSuperclass();
        this.type = ((ParameterizedType) superclass).getActualTypeArguments()[0];
    }

    public Type getType() { return type; }

    @SuppressWarnings("unchecked")
    public T cast(Object o) {
        if (type instanceof Class<?> c) return (T) c.cast(o);
        return (T) o;
    }

    @Override
    public String toString() { return type.getTypeName(); }
}

public class STM {
    private static final ThreadLocal<Map<TVar<?>, Object>> LOG = ThreadLocal.withInitial(HashMap::new);

    public static <T> T atomically(Supplier<T> action) {
        while (true) {
            LOG.set(new HashMap<>());
            try {
                T result = action.get();
                if (commit()) return result;
            } catch (RetryException e) {
                LOG.remove();
            }
        }
    }

    private static boolean commit() {
        // Simplified: validate and commit transaction log
        Map<TVar<?>, Object> log = LOG.get();
        synchronized (STM.class) {
            for (Map.Entry<TVar<?>, Object> e : log.entrySet())
                if (e.getKey().version != ((VersionedValue) e.getValue()).version) return false;
            log.forEach((v, val) -> v.commit(val));
        }
        return true;
    }
}

public class AsyncPipeline<T> {
