    public <R> AsyncPipeline<R> flatMap(Function<T, CompletableFuture<R>> fn) { return new AsyncPipeline<>(future.thenCompose(fn)); }
    public AsyncPipeline<T> recover(Function<Throwable, T> fn) { return new AsyncPipeline<>(future.exceptionally(fn)); }
