    public T await() throws Exception { return future.get(); }
}

public class Codec<A> {
    private final Function<A, JsonElement> encoder;
    private final Function<JsonElement, A> decoder;

    public Codec(Function<A, JsonElement> enc, Function<JsonElement, A> dec) {
        this.encoder = enc; this.decoder = dec;
    }

