public final class Lazy<T> {
    private volatile T value;
    private volatile boolean initialized = false;
    private final Supplier<T> initializer;

    public Lazy(Supplier<T> init) { this.initializer = init; }

    public T get() {
        if (!initialized) {
            synchronized (this) {
                if (!initialized) {
                    value = initializer.get();
                    initialized = true;
                }
            }
        }
        return value;
    }

    public <R> Lazy<R> map(Function<T, R> fn) { return new Lazy<>(() -> fn.apply(get())); }
    public boolean isInitialized() { return initialized; }
}

public class VirtualThreadPool {
    private final ExecutorService executor;
    private final Semaphore semaphore;

    public VirtualThreadPool(int maxConcurrent) {
        this.executor = Executors.newVirtualThreadPerTaskExecutor();
        this.semaphore = new Semaphore(maxConcurrent);
    }

    public <T> CompletableFuture<T> submit(Callable<T> task) {
        return CompletableFuture.supplyAsync(() -> {
            semaphore.acquireUninterruptibly();
            try { return task.call(); }
            catch (Exception e) { throw new CompletionException(e); }
            finally { semaphore.release(); }
        }, executor);
    }

    public void shutdown() { executor.shutdown(); }
}

public class HotObservable<T> {
    private final Subject<T> subject = new PublishSubject<>();
    private final Observable<T> multicast;
    private final Disposable connection;

    public HotObservable(Observable<T> source) {
        multicast = source.publish().refCount();
        connection = source.subscribe(subject::onNext, subject::onError, subject::onComplete);
    }

    public Disposable subscribe(Observer<T> observer) { return multicast.subscribe(observer); }
    public void dispose() { connection.dispose(); }
    public Observable<T> replay(int count) { return multicast.replay(count).autoConnect(); }
}

public class PersistentList<T> {
    private final T head;
    private final PersistentList<T> tail;
    private final int size;
    private static final PersistentList<?> EMPTY = new PersistentList<>();

    @SuppressWarnings("unchecked")
    public static <T> PersistentList<T> empty() { return (PersistentList<T>) EMPTY; }

    private PersistentList() { head = null; tail = null; size = 0; }
    private PersistentList(T head, PersistentList<T> tail) {
        this.head = head; this.tail = tail; this.size = tail.size + 1;
    }

    public PersistentList<T> prepend(T value) { return new PersistentList<>(value, this); }

    public T head() { if (isEmpty()) throw new NoSuchElementException(); return head; }
    public PersistentList<T> tail() { return tail; }
    public boolean isEmpty() { return size == 0; }
    public int size() { return size; }

    public <R> PersistentList<R> map(Function<T, R> fn) {
        if (isEmpty()) return empty();
        return tail.map(fn).prepend(fn.apply(head));
    }

    public PersistentList<T> filter(Predicate<T> pred) {
        if (isEmpty()) return empty();
        PersistentList<T> rest = tail.filter(pred);
        return pred.test(head) ? rest.prepend(head) : rest;
    }

    public List<T> toList() {
        List<T> result = new ArrayList<>();
        PersistentList<T> curr = this;
        while (!curr.isEmpty()) { result.add(curr.head()); curr = curr.tail(); }
        return result;
    }

    public static void main(String[] args) {
        var list = PersistentList.<Integer>empty().prepend(3).prepend(2).prepend(1);
        System.out.println(list.map(x -> x * 2).toList());
        System.out.println(list.filter(x -> x > 1).toList());
    }
}

public class ChronicleMap<K, V> {
    private final int segments;
    private final Map<K, V>[] maps;
    private final ReadWriteLock[] locks;

    @SuppressWarnings("unchecked")
    public ChronicleMap(int segments) {
        this.segments = segments;
        this.maps = new HashMap[segments];
        this.locks = new ReentrantReadWriteLock[segments];
        for (int i = 0; i < segments; i++) {
            maps[i] = new HashMap<>();
            locks[i] = new ReentrantReadWriteLock();
        }
    }

    private int segment(K key) { return Math.abs(key.hashCode() % segments); }

    public V get(K key) {
        int s = segment(key);
        locks[s].readLock().lock();
        try { return maps[s].get(key); }
        finally { locks[s].readLock().unlock(); }
    }

    public V put(K key, V value) {
        int s = segment(key);
        locks[s].writeLock().lock();
        try { return maps[s].put(key, value); }
        finally { locks[s].writeLock().unlock(); }
    }

    public V computeIfAbsent(K key, Function<K, V> fn) {
        int s = segment(key);
        locks[s].writeLock().lock();
        try { return maps[s].computeIfAbsent(key, fn); }
        finally { locks[s].writeLock().unlock(); }
    }

    public long size() {
        long total = 0;
        for (int i = 0; i < segments; i++) {
            locks[i].readLock().lock();
            try { total += maps[i].size(); }
            finally { locks[i].readLock().unlock(); }
        }
        return total;
    }
}

public class Actor<T> {
    private final BlockingQueue<T> mailbox = new LinkedBlockingQueue<>();
    private final Function<T, Void> behavior;
    private final ExecutorService executor;
    private volatile boolean running = true;

    public Actor(Function<T, Void> behavior, ExecutorService executor) {
        this.behavior = behavior;
        this.executor = executor;
        executor.submit(this::run);
    }

    private void run() {
        while (running) {
            try {
                T message = mailbox.poll(100, TimeUnit.MILLISECONDS);
                if (message != null) behavior.apply(message);
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); break; }
        }
    }

    public void send(T message) { mailbox.offer(message); }
    public void stop() { running = false; }

    public static class ActorSystem {
        private final ExecutorService pool;
        private final Map<String, Actor<?>> actors = new ConcurrentHashMap<>();

        public ActorSystem(int threads) { pool = Executors.newFixedThreadPool(threads); }

        public <T> Actor<T> create(String name, Function<T, Void> behavior) {
            Actor<T> actor = new Actor<>(behavior, pool);
            actors.put(name, actor);
            return actor;
        }

        @SuppressWarnings("unchecked")
        public <T> void send(String name, T message) {
            Actor<T> actor = (Actor<T>) actors.get(name);
            if (actor == null) throw new IllegalArgumentException("No actor: " + name);
            actor.send(message);
        }

        public void shutdown() {
            actors.values().forEach(Actor::stop);
            pool.shutdown();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ActorSystem system = new ActorSystem(4);
        Actor<String> logger = system.create("logger", msg -> { System.out.println("[LOG] " + msg); return null; });
        Actor<Integer> counter = system.create("counter", n -> { logger.send("Received: " + n); return null; });

        for (int i = 0; i < 5; i++) system.send("counter", i);
        Thread.sleep(500);
        system.shutdown();
    }
}

public class PatternMatcher<T, R> {
    private final List<Case<T, R>> cases = new ArrayList<>();
    private Function<T, R> defaultCase;

    @FunctionalInterface
    public interface Pattern<T> { boolean matches(T value); }

    public record Case<T, R>(Pattern<T> pattern, Function<T, R> handler) {}

    public PatternMatcher<T, R> when(Pattern<T> pattern, Function<T, R> handler) {
        cases.add(new Case<>(pattern, handler));
        return this;
    }

    public PatternMatcher<T, R> when(Predicate<T> pred, Function<T, R> handler) {
        return when(pred::test, handler);
    }

    public <S extends T> PatternMatcher<T, R> whenType(Class<S> type, Function<S, R> handler) {
        return when(type::isInstance, v -> handler.apply(type.cast(v)));
    }

    public PatternMatcher<T, R> otherwise(Function<T, R> handler) {
        this.defaultCase = handler;
        return this;
    }

    public PatternMatcher<T, R> otherwise(R value) {
        return otherwise(ignored -> value);
    }

    public R match(T value) {
        for (Case<T, R> c : cases) {
            if (c.pattern().matches(value)) return c.handler().apply(value);
        }
        if (defaultCase != null) return defaultCase.apply(value);
        throw new MatchError("No pattern matched: " + value);
    }

    public Function<T, R> toFunction() { return this::match; }

    public static class MatchError extends RuntimeException {
        public MatchError(String msg) { super(msg); }
    }

    public static void main(String[] args) {
        var matcher = new PatternMatcher<Object, String>()
            .whenType(Integer.class, n -> "Integer: " + n)
            .whenType(String.class, s -> "String: '" + s + "'")
            .whenType(Double.class, d -> "Double: " + String.format("%.2f", d))
            .when(obj -> obj == null, obj -> "null")
            .otherwise(obj -> "Unknown: " + obj.getClass().getSimpleName());

        for (Object val : new Object[]{42, "hello", 3.14, null, List.of(1, 2, 3)}) {
            System.out.println(matcher.match(val));
        }
    }
}
